import CryptoKit
import Foundation
import ProjectKit

/// One downloadable model: a pinned Hugging Face revision and its complete file inventory.
/// Generated by `scripts/speech/make-catalogue.py`; never edited by hand.
public struct ModelManifest: Codable, Sendable, Hashable, Identifiable {
    public struct File: Codable, Sendable, Hashable {
        /// Relative path inside the model directory.
        public var path: String
        public var size: Int64
        /// Lower-case hex SHA-256 of the file's bytes.
        public var sha256: String

        public init(path: String, size: Int64, sha256: String) {
            self.path = path
            self.size = size
            self.sha256 = sha256
        }
    }

    public var id: String
    public var repository: String
    /// Immutable commit SHA.
    public var revision: String
    public var format: String
    public var quantisation: String
    public var license: String
    public var attribution: String
    public var files: [File]

    public init(
        id: String, repository: String, revision: String, format: String, quantisation: String,
        license: String, attribution: String, files: [File]
    ) {
        self.id = id
        self.repository = repository
        self.revision = revision
        self.format = format
        self.quantisation = quantisation
        self.license = license
        self.attribution = attribution
        self.files = files
    }

    public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

    /// `https://huggingface.co/<repo>/resolve/<revision>/<path>`: pinned, so a moved branch can't change the bytes.
    public func downloadURL(for file: File) -> URL {
        var url = URL(string: "https://huggingface.co")!
        for part in repository.split(separator: "/") { url.append(path: String(part)) }
        url.append(path: "resolve")
        url.append(path: revision)
        for part in file.path.split(separator: "/") { url.append(path: String(part)) }
        return url
    }

    /// SHA-256 of the canonical (sorted-keys) manifest JSON: identifies exactly what was installed.
    public var digest: String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        let data = (try? encoder.encode(self)) ?? Data()
        return SHA256.hash(data: data).hexString
    }

    public var identity: ModelIdentity {
        ModelIdentity(
            catalogueID: id, repository: repository, revision: revision, manifestDigest: digest,
            quantisation: quantisation)
    }
}

/// The user-facing choice: two recognisers, each with the models it needs.
public enum SpeechEngine: String, Codable, Sendable, CaseIterable, Identifiable {
    case parakeet
    case qwen

    public var id: Self { self }

    public var title: String {
        switch self {
        case .parakeet: "Parakeet Ultra"
        case .qwen: "Qwen — Multilingual"
        }
    }

    public var summary: String {
        switch self {
        case .parakeet: "Local transcription with native word timing. 25 European languages."
        case .qwen:
            "Local transcription with broader language coverage (30 languages); fine timing for 9 of them uses an "
                + "additional alignment model."
        }
    }

    /// Catalogue ids, recogniser first.
    public var modelIDs: [String] {
        switch self {
        case .parakeet: [ModelCatalogue.parakeetID]
        case .qwen: [ModelCatalogue.qwenASRID, ModelCatalogue.qwenAlignerID]
        }
    }

    public var recogniserID: String { modelIDs[0] }
    public var alignerID: String? { self == .qwen ? ModelCatalogue.qwenAlignerID : nil }
}

public struct ModelCatalogue: Codable, Sendable, Hashable {
    public static let parakeetID = "parakeet-ultra-coreml"
    public static let qwenASRID = "qwen3-asr-1.7b-8bit"
    public static let qwenAlignerID = "qwen3-aligner-0.6b-8bit"

    public var schemaVersion: Int
    public var models: [ModelManifest]

    public init(schemaVersion: Int, models: [ModelManifest]) {
        self.schemaVersion = schemaVersion
        self.models = models
    }

    public func manifest(_ id: String) -> ModelManifest? { models.first { $0.id == id } }

    public func manifests(for engine: SpeechEngine) -> [ModelManifest] { engine.modelIDs.compactMap(manifest) }

    public func downloadBytes(for engine: SpeechEngine) -> Int64 {
        manifests(for: engine).reduce(0) { $0 + $1.totalBytes }
    }

    /// The catalogue shipped in this module's resources.
    public static let bundled: ModelCatalogue = {
        guard let url = Bundle.module.url(forResource: "catalogue", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let catalogue = try? JSONDecoder().decode(ModelCatalogue.self, from: data)
        else { return ModelCatalogue(schemaVersion: 1, models: []) }
        return catalogue
    }()
}

extension Digest {
    public var hexString: String { map { String(format: "%02x", $0) }.joined() }
}

public enum Fingerprint {
    /// SHA-256 hex of the sorted-keys JSON of `value`.
    public static func of<T: Encodable>(_ value: T) -> String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        encoder.dateEncodingStrategy = .iso8601
        let data = (try? encoder.encode(value)) ?? Data()
        return SHA256.hash(data: data).hexString
    }

    public static func of(strings: [String]) -> String {
        SHA256.hash(data: Data(strings.joined(separator: "\u{1F}").utf8)).hexString
    }
}
